50	/**
51	 * Provides different locks to handle concurrency in OzoneMaster.
52	 * We also maintain lock hierarchy, based on the weight.
53	 *
54	 * <table>
55	 *   <caption></caption>
56	 *   <tr>
57	 *     <td><b> WEIGHT </b></td> <td><b> LOCK </b></td>
58	 *   </tr>
59	 *   <tr>
60	 *     <td> 0 </td> <td> S3 Bucket Lock </td>
61	 *   </tr>
62	 *   <tr>
63	 *     <td> 1 </td> <td> Volume Lock </td>
64	 *   </tr>
65	 *   <tr>
66	 *     <td> 2 </td> <td> Bucket Lock </td>
67	 *   </tr>
68	 *   <tr>
69	 *     <td> 3 </td> <td> User Lock </td>
70	 *   </tr>
71	 *   <tr>
72	 *     <td> 4 </td> <td> S3 Secret Lock</td>
73	 *   </tr>
74	 *   <tr>
75	 *     <td> 5 </td> <td> Prefix Lock </td>
76	 *   </tr>
77	 * </table>
78	 *
79	 * One cannot obtain a lower weight lock while holding a lock with higher
80	 * weight. The other way around is possible. <br>
81	 * <br>
82	 * <p>
83	 * For example:
84	 * <br>
85	 * {@literal ->} acquire volume lock (will work)<br>
86	 *   {@literal +->} acquire bucket lock (will work)<br>
87	 *     {@literal +-->} acquire s3 bucket lock (will throw Exception)<br>
88	 * </p>
89	 * <br>
90	 */
91	
92	public class OzoneManagerLock implements IOzoneManagerLock {
93	  private static final Logger LOG =
94	      LoggerFactory.getLogger(OzoneManagerLock.class);
95	
96	  private final Map<Resource, Striped<ReadWriteLock>> stripedLockByResource;
97	
98	  private OMLockMetrics omLockMetrics;
99	  private final ThreadLocal<Short> lockSet = ThreadLocal.withInitial(
100	      () -> Short.valueOf((short)0));
101	
102	  private ThreadLocal<OMLockDetails> omLockDetails =
103	      ThreadLocal.withInitial(OMLockDetails::new);
104	
105	  /**
106	   * Creates new OzoneManagerLock instance.
107	   * @param conf Configuration object
108	   */
109	  public OzoneManagerLock(ConfigurationSource conf) {
110	    omLockMetrics = OMLockMetrics.create();
111	    Map<Resource, Striped<ReadWriteLock>> stripedLockMap =
112	        new EnumMap<>(Resource.class);
113	    for (Resource r : Resource.values()) {
114	      stripedLockMap.put(r, createStripeLock(r, conf));
115	    }
116	    this.stripedLockByResource = Collections.unmodifiableMap(stripedLockMap);
117	  }
118	
119	  private Striped<ReadWriteLock> createStripeLock(Resource r,
120	      ConfigurationSource conf) {
121	    boolean fair = conf.getBoolean(OZONE_MANAGER_FAIR_LOCK,
122	        OZONE_MANAGER_FAIR_LOCK_DEFAULT);
123	    String stripeSizeKey = OZONE_MANAGER_STRIPED_LOCK_SIZE_PREFIX +
124	        r.getName().toLowerCase();
125	    int size = conf.getInt(stripeSizeKey,
126	        OZONE_MANAGER_STRIPED_LOCK_SIZE_DEFAULT);
127	    return SimpleStriped.readWriteLock(size, fair);
128	  }
129	
130	  private Iterable<ReadWriteLock> bulkGetLock(Resource resource, Collection<String[]> keys) {
131	    Striped<ReadWriteLock> striped = stripedLockByResource.get(resource);
132	    List<Object> lockKeys = new ArrayList<>(keys.size());
133	    for (String[] key : keys) {
134	      if (Objects.nonNull(key)) {
135	        lockKeys.add(CompositeKey.combineKeys(key));
136	      }
137	    }
138	    return striped.bulkGet(lockKeys);
139	  }
140	
141	  private ReentrantReadWriteLock getLock(Resource resource, String... keys) {
142	    Striped<ReadWriteLock> striped = stripedLockByResource.get(resource);
143	    Object key = combineKeys(keys);
144	    return (ReentrantReadWriteLock) striped.get(key);
145	  }
