18	package org.apache.hadoop.ozone.om.snapshot;
19	
20	import java.util.ArrayList;
21	import java.util.Arrays;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.Objects;
25	import java.util.UUID;
26	import java.util.stream.Collectors;
27	import org.apache.hadoop.ozone.om.exceptions.OMException;
28	import org.apache.hadoop.ozone.om.lock.IOzoneManagerLock;
29	import org.apache.hadoop.ozone.om.lock.OMLockDetails;
30	import org.apache.hadoop.ozone.om.lock.OzoneManagerLock;
31	
32	/**
33	 * Class to take multiple locks on multiple snapshots.
34	 */
35	public class MultiSnapshotLocks {
36	  private final List<String[]> objectLocks;
37	  private final IOzoneManagerLock lock;
38	  private final OzoneManagerLock.Resource resource;
39	  private final boolean writeLock;
40	  private OMLockDetails lockDetails;
41	
42	  public MultiSnapshotLocks(IOzoneManagerLock lock, OzoneManagerLock.Resource resource, boolean writeLock) {
43	    this.writeLock = writeLock;
44	    this.resource = resource;
45	    this.lock = lock;
46	    this.objectLocks = new ArrayList<>();
47	    this.lockDetails = OMLockDetails.EMPTY_DETAILS_LOCK_NOT_ACQUIRED;
48	  }
49	
50	  public synchronized OMLockDetails acquireLock(Collection<UUID> ids) throws OMException {
51	    if (this.lockDetails.isLockAcquired()) {
52	      throw new OMException(
53	          objectLocks.stream().map(Arrays::toString).collect(Collectors.joining(",",
54	              "More locks cannot be acquired when locks have been already acquired. Locks acquired : [", "]")),
55	          OMException.ResultCodes.INTERNAL_ERROR);
56	    }
57	    List<String[]> keys =
58	        ids.stream().filter(Objects::nonNull).map(id -> new String[] {id.toString()})
59	            .collect(Collectors.toList());
60	    OMLockDetails omLockDetails = this.writeLock ? lock.acquireWriteLocks(resource, keys) :
61	        lock.acquireReadLocks(resource, keys);
62	    if (omLockDetails.isLockAcquired()) {
63	      objectLocks.addAll(keys);
64	    }
65	    this.lockDetails = omLockDetails;
66	    return omLockDetails;
67	  }
68	
69	  public synchronized void releaseLock() {
70	    if (this.writeLock) {
71	      lockDetails = lock.releaseWriteLocks(resource, this.objectLocks);
72	    } else {
73	      lockDetails = lock.releaseReadLocks(resource, this.objectLocks);
74	    }
75	    this.objectLocks.clear();
76	  }
77	
78	  List<String[]> getObjectLocks() {
79	    return objectLocks;
80	  }
81	
82	  public boolean isLockAcquired() {
83	    return lockDetails.isLockAcquired();
84	  }
85	}
